module jt054156_a4h(
    input  wire [3:0] a,
    input  wire [3:0] b,
    input  wire       ci,
    output wire [3:0] s,
    output wire       co
);

assign { co, s } = { 1'b0, a } + { 1'b0, b } + { 4'b0, ci };

endmodule

module jt054156_a1n(
    input  wire a,
    input  wire b,
    input  wire ci,
    output wire s,
    output wire co
);

wire [1:0] sum;

assign sum = { 1'b0, a } + { 1'b0, b } + { 1'b0, ci };
assign s   = sum[0];
assign co  = sum[1];

endmodule

module jt054156_a1a(
    input  wire a,
    input  wire b,
    output wire s,
    output wire co
);

assign s  = a ^ b;
assign co = a & b;

endmodule

module jt054156_a2n(
    input  wire [1:0] a,
    input  wire [1:0] b,
    input  wire       ci,
    output wire [1:0] s,
