wire select_b =  sa & ~sb;

assign x1 = (select_a & a1) | (select_b & b1);
assign x2 = (select_a & a2) | (select_b & b2);
assign x3 = (select_a & a3) | (select_b & b3);
assign x4 = (select_a & a4) | (select_b & b4);

endmodule

module jt054156_t2b(
