module jt054156_fdm(
    input  wire ck,
    input  wire d,
    output reg  q,
    output wire nq
);

always @(posedge ck) begin
    q <= d;
end

assign nq = ~q;

endmodule

module jt054156_fdn(
    input  wire ck,
    input  wire d,
    input  wire ns,
    output reg  q,
    output wire nq
);

always @(posedge ck or negedge ns) begin
    if (!ns) begin
        q <= 1'b1;
    end else begin
        q <= d;
    end
end

assign nq = ~q;

endmodule

