module jt054156_c43(
    input  wire       ck,
    input  wire [3:0] d,
    input  wire       load_n,
    input  wire       en,
    input  wire       ci,
    input  wire       clear_n,
    output reg  [3:0] q,
    output wire       co
);

always @(posedge ck or negedge clear_n) begin
    if (!clear_n) begin
        q <= 4'd0;
    end else if (!load_n) begin
        q <= d;
    end else if (en & ci) begin
        q <= q + 1'b1;
    end
end

assign co = &{ q, ci };

endmodule

module jt054156_de6(
    input  wire       s1,
    input  wire       s2,
    input  wire       s3,
    input  wire       g1,
    input  wire       g2_n,
    input  wire       g3_n,
    output wire [7:0] x_n
);

wire       enabled = g1 & ~g2_n & ~g3_n;
wire [2:0] sel     = { s3, s2, s1 };
wire [7:0] onehot;

assign onehot = 8'b0000_0001 << sel;
assign x_n    = enabled ? ~onehot : 8'hff;

endmodule

module jt054156_de4(
    input  wire       a,
    input  wire       b,
    input  wire       g_n,
    output wire [3:0] x_n
);

wire       enabled = ~g_n;
wire [1:0] sel     = { b, a };
wire [3:0] onehot;

assign onehot = 4'b0001 << sel;
assign x_n    = enabled ? ~onehot : 4'hf;

endmodule


